(()=>{const b=[...document.querySelectorAll('[data-theme-choice]')];const set=t=>{document.body.dataset.theme=t;b.forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.themeChoice===t)));try{localStorage.setItem('sobre-rodas-concept-theme',t)}catch{}};let t='one';try{t=localStorage.getItem('sobre-rodas-concept-theme')||t}catch{}set(t);b.forEach(x=>x.addEventListener('click',()=>set(x.dataset.themeChoice)))})();
